+import type { SessionEvent } from '../types.ts';
+
+// Shortcuts that make work look done. The run's own changes are scanned at a done claim; findings are flags, not refusals.
+export type FileChange = { path: string; added: string[]; removed: string[]; deleted: boolean };
+export type Rule = 'test-deleted' | 'test-weakened' | 'test-skipped' | 'suppression' | 'swallowed-error' | 'type-escape' | 'stub';
+export type Finding = { rule: Rule; path: string; detail?: string };
+
+const TEST_PATH = /(^|\/)(tests?|__tests__)\/|[._](test|spec)\.[a-z]+$|(^|\/)test_[^/]*$/;
+const PROSE = /\.(md|mdx|txt|rst|adoc)$/;
+const ASSERT = /\b(assert|expect)\b/;
+const SKIP = /\b(test|it|describe)\.skip\(|\bx(it|describe|test)\(|\bt\.Skip\(|@pytest\.mark\.skip|\bpytest\.skip\(|\bit\.todo\(/;
+const SUPPRESS = /@ts-(ignore|expect-error|nocheck)|eslint-disable|# type: ignore|# noqa|pylint: disable|\/\/ nolint/;
+const SWALLOW = /catch\s*(\([^)]*\))?\s*\{\s*\}|^\s*except\b.*:\s*pass\s*$/;
+const TYPE_ESCAPE = /\bas any\b|:\s*any\b|<any>/;
+const STUB = /not implemented|NotImplementedError|unimplemented!|todo!\(/i;
+
+const lines = (s: unknown) => (typeof s === 'string' && s ? s.split('\n') : []);
+
+// Reads a `git diff-tree -p -U0` patch: a file header, then hunks whose +/- lines are the change.
+export function changesFromPatch(patch: string): FileChange[] {
+  const out: FileChange[] = [];
+  let cur: FileChange | undefined;
+  let inHunk = false;
+  for (const line of patch.split('\n')) {
+    const head = /^diff --git a\/.* b\/(.*)$/.exec(line);
+    if (head) {
+      cur = { path: head[1]!, added: [], removed: [], deleted: false };
+      out.push(cur);
+      inHunk = false;
+      continue;
+    }
+    if (!cur) continue;
+    if (line.startsWith('deleted file mode')) cur.deleted = true;
+    if (line.startsWith('@@')) inHunk = true;
+    else if (!inHunk) continue;
+    else if (line.startsWith('+')) cur.added.push(line.slice(1));
+    else if (line.startsWith('-')) cur.removed.push(line.slice(1));
+  }
+  return out;
+}
+
+// Without snapshots, the changes are the edit and write calls that completed in these events.
+export function changesFromCalls(events: SessionEvent[]): FileChange[] {
+  const done = new Set(events.flatMap((e) => (e.kind === 'tool_result' && e.status === 'completed' ? [e.callId] : [])));
+  const out: FileChange[] = [];
+  for (const e of events) {
+    if (e.kind !== 'tool_intent' || !done.has(e.callId)) continue;
+    const path = String(e.input.path ?? '');
+    if (e.tool === 'write') out.push({ path, added: lines(e.input.content), removed: [], deleted: false });
+    else if (e.tool === 'edit' && Array.isArray(e.input.edits))
+      for (const ed of e.input.edits as { old_text?: unknown; new_text?: unknown }[]) out.push({ path, added: lines(ed.new_text), removed: lines(ed.old_text), deleted: false });
+  }
+  return out;
+}
+
+export function findSlop(changes: FileChange[]): Finding[] {
+  const out: Finding[] = [];
+  for (const c of changes) {
+    const test = TEST_PATH.test(c.path);
+    if (c.deleted) {
+      if (test) out.push({ rule: 'test-deleted', path: c.path });
+      continue;
+    }
+    if (test) {
+      if (c.removed.filter((l) => ASSERT.test(l)).length > c.added.filter((l) => ASSERT.test(l)).length) out.push({ rule: 'test-weakened', path: c.path });
+      for (const l of c.added) if (SKIP.test(l)) out.push({ rule: 'test-skipped', path: c.path });
+    }
+    if (PROSE.test(c.path)) continue;
+    for (const l of c.added) {
+      if (SUPPRESS.test(l)) out.push({ rule: 'suppression', path: c.path, detail: l.trim() });
+      if (SWALLOW.test(l)) out.push({ rule: 'swallowed-error', path: c.path });
+      if (TYPE_ESCAPE.test(l)) out.push({ rule: 'type-escape', path: c.path });
+      if (STUB.test(l)) out.push({ rule: 'stub', path: c.path });
+    }
+  }
+  return out;
