--- a/src/core/trust/slop.ts	1970-01-01 00:00:00.000000000 +0000
+++ b/src/core/trust/slop.ts	2026-10-28 06:42:01.350391312 +0000
@@ -0,0 +1,55 @@
+// Slop: shortcuts that make work look done. Pure: it reads the run's changes, never the model's claims.
+export type FileChange = { path: string; added: string[]; removed: string[]; deleted: boolean };
+export type Finding = { rule: string; path: string; detail?: string };
+
+const CODE = /\.(c|cc|cpp|cs|go|h|java|js|jsx|kt|mjs|cjs|php|py|rb|rs|sh|swift|ts|tsx)$/;
+const TEST_FILE = /\.(test|spec)\.|_test\.go$|(^|\/)test_[^/]*$|(^|\/)tests?\//;
+const ASSERT = /\bexpect\(|\bassert|\bt\.(Error|Fatal)/;
+const SKIP = /\b(it|test|describe)\.skip\(|\bx(it|describe|test)\(|\bt\.Skip\w*\(|@(pytest\.mark\.skip|unittest\.skip)|#\[ignore\]/;
+const LINE_RULES: [string, RegExp][] = [
+  ['suppression', /@ts-(ignore|nocheck)\b|eslint-disable|#\s*type:\s*ignore|#\s*noqa\b|\/\/\s*nolint\b/],
+  ['swallowed-error', /catch\s*(\([^)]*\))?\s*\{\s*\}|\bexcept\b[^:]*:\s*pass\b/],
+  ['type-escape', /\bas any\b|<any>|:\s*any\b/],
+  ['stub', /not implemented|NotImplementedError|\btodo!\(|\bunimplemented!\(/i],
+];
+
+export function findSlop(changes: FileChange[]): Finding[] {
+  return changes.flatMap((c): Finding[] => {
+    if (!CODE.test(c.path)) return [];
+    const isTest = TEST_FILE.test(c.path);
+    if (c.deleted) return isTest ? [{ rule: 'test-deleted', path: c.path }] : [];
+    const out: Finding[] = [];
+    if (isTest && c.removed.filter((l) => ASSERT.test(l)).length > c.added.filter((l) => ASSERT.test(l)).length)
+      out.push({ rule: 'test-weakened', path: c.path });
+    for (const line of c.added) {
+      if (isTest && SKIP.test(line)) out.push({ rule: 'test-skipped', path: c.path, detail: line.trim() });
+      else {
+        const hit = LINE_RULES.find(([, re]) => re.test(line));
+        if (hit) out.push({ rule: hit[0], path: c.path, detail: line.trim() });
+      }
+    }
+    return out;
+  });
+}
+
+export const flagText = (f: Finding) => `${f.rule} ${f.path}${f.detail ? `: ${f.detail.slice(0, 120)}` : ''}`;
+
+// Reads a `git diff-tree -p -U0` patch: hunk lines only, file headers skipped.
+export function changesFromPatch(patch: string): FileChange[] {
+  const out: FileChange[] = [];
+  let cur: FileChange | undefined;
+  let inHunk = false;
+  for (const line of patch.split('\n')) {
+    const head = /^diff --git a\/(.*) b\/(.*)$/.exec(line);
+    if (head) {
+      cur = { path: head[2]!, added: [], removed: [], deleted: false };
+      out.push(cur);
+      inHunk = false;
+    } else if (!cur) continue;
+    else if (line.startsWith('@@')) inHunk = true;
+    else if (line.startsWith('deleted file mode')) cur.deleted = true;
+    else if (inHunk && line.startsWith('+')) cur.added.push(line.slice(1));
+    else if (inHunk && line.startsWith('-')) cur.removed.push(line.slice(1));
+  }
+  return out;
+}
