+    // 6 + 4 mugs = 10 units -> 5% off
+    expect(totals(cart('US', [['MUG', 6], ['MUG', 4]]))).toMatchObject({ subtotal: 4275 });
+  });
+
+  test('shipping threshold is judged after the coupon', () => {
