+    expect(t).toMatchObject({ subtotal: 4400, coupon: 440, shipping: 700 });
+  });
+
+  test('UK free shipping starts at 4000', () => {
+    expect(totals(cart('UK', [['BAG', 2]]))).toMatchObject({ shipping: 0 });
+  });
+});

